public void LoadData()
{
    SIM_Branch obj = new SIM_Branch();
    DataTable dtbResult = null;

    if (chkFullYear.Checked)
    {
        // Tạo 2 ManualResetEvent để chạy song song HK1 và HK2
        ManualResetEvent mre1 = new ManualResetEvent(false);
        ManualResetEvent mre2 = new ManualResetEvent(false);

        DataTable dtbHK1 = null;
        DataTable dtbHK2 = null;
        Exception exHK1 = null;
        Exception exHK2 = null;

        // Luồng load HK1
        ThreadPool.QueueUserWorkItem(delegate
        {
            try
            {
                dtbHK1 = obj.GetDataTable(
                    "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
                    "@ScienceIDOfTeacher", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupIDOfTeacher", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", "1"
                );
            }
            catch (Exception ex)
            {
                exHK1 = ex;
            }
            finally
            {
                mre1.Set();
            }
        });

        // Luồng load HK2
        ThreadPool.QueueUserWorkItem(delegate
        {
            try
            {
                dtbHK2 = obj.GetDataTable(
                    "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
                    "@ScienceIDOfTeacher", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupIDOfTeacher", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", "2"
                );
            }
            catch (Exception ex)
            {
                exHK2 = ex;
            }
            finally
            {
                mre2.Set();
            }
        });

        // Chờ cả 2 luồng hoàn thành
        WaitHandle.WaitAll(new WaitHandle[] { mre1, mre2 });

        // Kiểm tra lỗi
        if (exHK1 != null)
        {
            Invoke(new MethodInvoker(delegate
            {
                ErrorManager.Error(exHK1.Message);
                EndProcess();
            }));
            return;
        }

        if (exHK2 != null)
        {
            Invoke(new MethodInvoker(delegate
            {
                ErrorManager.Error(exHK2.Message);
                EndProcess();
            }));
            return;
        }

        // Gộp và tính tổng trên background thread
        dtbResult = MergeAndSumByTeacher(dtbHK1, dtbHK2);
    }
    else
    {
        dtbResult = obj.GetDataTable(
            "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
            "@ScienceIDOfTeacher", uSubjectGroup.ScienceEditValue,
            "@SubjectGroupIDOfTeacher", uSubjectGroup.SubjectGroupEditValue,
            "@TeacherID", lookupTeacherID.EditValue,
            "@YearID", uYearSemester.YearIDEditValue,
            "@Semester", uYearSemester.SemesterEditValue
        );
    }

    // Quay về UI thread để bind grid
    Invoke(new MethodInvoker(delegate
    {
        dtbData = dtbResult;

        if (dtbData == null || dtbData.Rows.Count == 0)
        {
            gcData.DataSource = null;
            MessageManager.Warning("Không có dữ liệu!");
            EndProcess();
            return;
        }

        AddComputedColumns();
        InitGrid();
        gcData.DataSource = dtbData;
        gvData.BestFitColumns();

        if (chkHasTeachingHours.Checked)
            dtbData.DefaultView.RowFilter = "TongLTTH > 0";

        EndProcess();
    }));
}

